def has_tag(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def existing_permission(statements,focus_id,want_employee,want_contractor):
    for statement in statements:
        if focus_id not in statement.get('support_ids',[]):
            continue
        term=statement.get('term')
        if not has_tag(term,'permission') or not has_tag(term,'disclose') or not has_tag(term,'confidential_information'):
            continue
        if want_employee and not has_tag(term,'employees_of'):
            continue
        if want_contractor and not has_tag(term,'independent_contractors_of'):
            continue
        return True
    return False

def exact_focus_evidence(answer,focus_id,focus_text):
    evidence=answer.get('evidence',[])
    for item in evidence:
        if item.get('unit_id')!=focus_id:
            continue
        quote=item.get('quote','')
        if isinstance(quote,str) and quote and quote in focus_text:
            return True
    return False

def add_statement(statements,term,support_ids):
    for statement in statements:
        if statement.get('term')==term:
            return
    statements.append({'term':term,'support_ids':support_ids})

def add_unresolved(unresolved,message):
    if message not in unresolved:
        unresolved.append(message)

def recipient_union(want_employee,want_contractor):
    owner=['receiving_party']
    if want_employee and want_contractor:
        return ['participant_union',['employees_of',owner],['independent_contractors_of',owner]]
    if want_employee:
        return ['employees_of',owner]
    return ['independent_contractors_of',owner]

def apply(inputs,premises):
    source_output=inputs.get('source_output',{})
    statements=[]
    for statement in source_output.get('statements',[]):
        statements.append(statement)
    unresolved=[]
    for message in source_output.get('unresolved',[]):
        add_unresolved(unresolved,message)
    answers={}
    for answer in inputs.get('semantic_answers',[]):
        answers[answer.get('id')]=answer
    for unit in inputs.get('source_spans',[]):
        if not is_candidate(unit):
            continue
        focus_id=unit.get('id')
        raw=unit.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        t=raw.casefold()
        lexical_employee='employee' in t
        lexical_contractor='contractor' in t
        if existing_permission(statements,focus_id,lexical_employee,lexical_contractor):
            continue
        query_id='limited_personnel_disclosure_'+str(focus_id)
        answer=answers.get(query_id)
        if answer is None:
            add_unresolved(unresolved,'Personnel disclosure permission at unit '+str(focus_id)+' was not semantically resolved.')
            continue
        choice=answer.get('choice')
        if not exact_focus_evidence(answer,focus_id,raw):
            add_unresolved(unresolved,'Personnel disclosure permission at unit '+str(focus_id)+' lacks exact current-unit evidence.')
            continue
        want_employee=False
        want_contractor=False
        if choice=='employees_and_contractors':
            want_employee=True
            want_contractor=True
        elif choice=='employees_only':
            want_employee=True
        elif choice=='contractors_only':
            want_contractor=True
        else:
            add_unresolved(unresolved,'Personnel disclosure permission at unit '+str(focus_id)+' remains unknown.')
            continue
        if want_employee!=lexical_employee or want_contractor!=lexical_contractor:
            add_unresolved(unresolved,'Personnel classification at unit '+str(focus_id)+' conflicts with the current clause text.')
            continue
        recipients=recipient_union(want_employee,want_contractor)
        condition=['and_condition',['need_to_know','source-stated need to know'],['confidentiality_bound','source-stated confidentiality obligation']]
        term=['permission',['receiving_party'],['disclose',['confidential_information'],recipients],condition]
        add_statement(statements,term,[focus_id])
    complete=bool(source_output.get('complete',False)) and not unresolved
    return {'statements':statements,'complete':complete,'unresolved':unresolved}

