def context_relevant(unit):
    raw=unit.get('text','')
    if not isinstance(raw,str):
        raw=str(raw)
    t=raw.casefold()
    return 'confidential information' in t and ('disclos' in t or 'third part' in t or 'restrict access' in t)

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    queries=[]
    i=0
    while i<len(spans):
        unit=spans[i]
        if is_candidate(unit):
            ids=[]
            if i>0 and context_relevant(spans[i-1]):
                ids.append(spans[i-1].get('id'))
            ids.append(unit.get('id'))
            queries.append({'id':'limited_personnel_disclosure_'+str(unit.get('id')),'operation':'limited_personnel_disclosure_permission','unit_ids':ids})
        i+=1
    return {'queries':queries}
